/*
 * POTACAT socket audio backend for Dire Wolf (GPL-2.0, same as Dire Wolf).
 *
 * ADEVICE tcp:<port> makes Dire Wolf take its receive audio from, and send
 * its transmit audio to, a loopback TCP port that POTACAT serves
 * (lib/modem-audio-server.js: raw signed 16-bit little-endian mono PCM both
 * ways, no framing, at the ARATE Dire Wolf was configured with). Dire Wolf
 * then opens no sound device at all — POTACAT owns the radio's audio, on a
 * Flex over its own stream, on any other rig through its audio bridge.
 *
 * Transmit audio is PACED like a sound card: a socket takes a whole frame in
 * a millisecond, but POTACAT plays it in real time and keeps at most ~300 ms
 * of backlog, so tcpaudio_flush() blocks whenever the audio written so far is
 * more than TCPAUDIO_LEAD_MS ahead of the playback clock, and
 * tcpaudio_wait() (audio_wait) sleeps until the last byte has "played" — the
 * moment Dire Wolf may drop PTT, exactly as snd_pcm_drain() gives it.
 *
 * Hooked into audio.c / audio_win.c / audio_portaudio.c by
 * third_party/direwolf/potacat-socket-audio.patch, generated by
 * scripts/gen-direwolf-patch.py from the pinned sources. Same shape as
 * ardopcf's SocketAudio.c.
 */
#ifndef AUDIO_TCP_H
#define AUDIO_TCP_H 1

/* Non-zero when spec is "tcp:<port>" (case-insensitive). */
int tcpaudio_is_spec (const char *spec);

/* Connect to 127.0.0.1:<port>. Returns 0, or -1 with a message printed. */
int tcpaudio_open (const char *spec, int samples_per_sec, int num_channels, int bits_per_sample);

/* True between a successful open and close. */
int tcpaudio_active (void);

/* Blocking read of up to max bytes. Returns the count, 0 on EOF, -1 on error. */
int tcpaudio_read (unsigned char *buf, int max);

/* Queue one transmit byte; sent on flush or when the buffer fills. */
int tcpaudio_put (int c);

/* Send what is queued, pacing against the playback clock. 0, or -1 on error. */
int tcpaudio_flush (void);

/* Flush, then sleep until everything written has played out. */
void tcpaudio_wait (void);

void tcpaudio_close (void);

#endif
